/* scan729spec.h — test_pmt.py `Scan729spec` (ARTIQ 8) on RISC-Q, method for method.
 *
 * Every ARTIQ method of the class is a C function of the same name with the same body order; the
 * floating-point quantities ARTIQ evaluates on the host (frequencies -> FTW, dB -> attenuator code,
 * delay() / seconds_to_mu() -> machine units) arrive pre-computed in the int32 parameter table P (the
 * P_* indices are generated by riscq/ion/port.py with ARTIQ 8's own arithmetic). Beam / line names:
 *     U0C2 = urukul0_ch2 (854)   U1C0 / U1C1 / U1C2 / U1C3 = urukul1_ch0 / ch1 (729) / ch2 (397) / ch3
 *     PMT  = ttl0_counter (input line 8) */
#ifndef SCAN729SPEC_H
#define SCAN729SPEC_H

/* Dopplercooling(coolingtime=1000, detuning=6.5, att=16) */
static void Dopplercooling(volatile int32_t *P) {
    sw_on(U0C2);                                   /* turn on 854 */
    delay_mu(P[P_D10US]);
    att_set(U1C2, P[P_ATT_COOL]);
    core_break_realtime();
    delay_mu(P[P_D40US]);
    dds_set(U1C2, P[P_F_COOL], P[P_A_FULL]);       /* (resonantfreq - detuning) MHz, amplitude=1.0 */
    delay_mu(P[P_D20US]);
    sw_on(U1C2);
    delay_mu(P[P_D_COOLINGTIME]);
    sw_off(U1C2);
    delay_mu(P[P_D10US]);
}

/* spinpol729(spinpol_729_round=10) */
static void spinpol729(volatile int32_t *P) {
    core_break_realtime();
    delay_mu(P[P_D_SLACK_SPI]);
    sw_off(U0C2);                                  /* turn off 854 */
    sw_off(U1C2);                                  /* turn off 397 */
    sw_off(U1C1);                                  /* turn off 729 */
    att_set(U1C1, P[P_ATT_729]);
    delay_mu(P[P_D10US]);
    dds_set(U1C1, P[P_F_SPINPOL], P[P_A_FULL]);
    delay_mu(P[P_D10US]);
    for (int32_t rr = 0; rr < P[P_SPINPOL_ROUNDS]; rr++) {
        delay_mu(P[P_D5US]);
        sw_on(U1C1);
        delay_mu(P[P_D_SPINPOL_PERIOD]);
        sw_off(U1C1);
        delay_mu(P[P_D5US]);
        sw_on(U0C2);
        delay_mu(P[P_D_REPUMP_PERIOD]);
        sw_off(U0C2);
        delay_mu(P[P_D10US]);
    }
    att_set(U1C1, P[P_ATT_729]);
    delay_mu(P[P_D5US]);
}

/* cspinpol(freq=145.688, att=25, flag_setfreq=False) */
static void cspinpol(volatile int32_t *P) {
    att_set(U0C2, P[P_ATT_CSP_854]);
    att_set(U1C1, P[P_ATT_729]);
    dds_set(U1C1, P[P_F_SPINPOL], P[P_A_FULL]);
    delay_mu(P[P_D10US]);
    sw_on(U1C1);
    sw_on(U0C2);
    delay_mu(P[P_D100US]);
    sw_off(U1C1);
    sw_off(U0C2);
    delay_mu(P[P_D10US]);
    att_set(U0C2, P[P_ATT_10]);
    att_set(U1C1, P[P_ATT_729]);
}

/* ionshelving(Dfreq, Datt, period=2) */
static void ionshelving(volatile int32_t *P, volatile int32_t *pmt, int32_t *npmt) {
    att_set(U1C2, P[P_ATT_6]);
    delay_mu(P[P_D70US]);
    dds_set(U1C2, P[P_F_CHECK], P[P_A_FULL]);      /* checkfreq = Dfreq - 4 */
    delay_mu(P[P_D5US]);
    sw_on(U1C2);
    pmt[*npmt] = pmt_number(P, P[P_GATE_DETECT]);  /* record_data(self.pmt_number(period)) */
    (*npmt)++;
    delay_mu(P[P_D50US]);
    core_break_realtime();
    sw_off(U1C2);
    delay_mu(P[P_D5US]);
}

/* spec729(spec_729_span, spec_729_period, reptime=100, flag_spinpol, flag_cspinpol=False) */
static void spec729(volatile int32_t *P, volatile int32_t *span, int32_t npts, int32_t reptime,
                    volatile int32_t *pmt) {
    int32_t npmt = 0;
    core_break_realtime();
    sw_on(U0C2);                                   /* turn on 854 */
    sw_off(U1C1);                                  /* turn off 729 AOM1 */
    sw_off(U1C0);                                  /* turn off 729 AOM2 t2 */
    delay_mu(P[P_D200US]);
    att_set(U1C3, P[P_ATT_11]);                    /* for mt turn on 729 AOM2 t1 */
    dds_set(U1C3, P[P_F_100MHZ], P[P_A_FULL]);
    sw_on(U1C3);
    delay_mu(P[P_D200US]);
    delay_mu(P[P_D5US]);
    for (int32_t p = 0; p < npts; p++) {
        for (int32_t ii = 0; ii < reptime; ii++) {
            Dopplercooling(P);
            delay_mu(P[P_D5US]);
            if (P[P_FLAG_SPINPOL]) spinpol729(P);
            if (P[P_FLAG_CSPINPOL]) cspinpol(P);
            dds_set(U1C1, span[p], P[P_A_FULL]);   /* set 729 freq */
            sw_off(U0C2);                          /* turn off 854 */
            delay_mu(P[P_D5US]);
            att_set(U1C1, P[P_ATT_729]);
            delay_mu(P[P_D5US]);
            sw_on(U1C1);                           /* turn on 729 */
            delay_mu(P[P_D_SPEC_PERIOD]);
            sw_off(U1C1);                          /* turn off 729 */
            delay_mu(P[P_D5US]);
            ionshelving(P, pmt, &npmt);
            sw_on(U0C2);                           /* turn on 854 */
            delay_mu(P[P_D50US]);
        }
    }
    delay_mu(P[P_D100US]);
    att_set(U1C2, P[P_ATT_10]);
    dds_set(U1C2, P[P_F_END], P[P_A_FULL]);        /* (90 + respoint/2 - 10) MHz */
    sw_on(U1C2);                                   /* turn on 397 */
    delay_mu(P[P_D100US]);
}

/* Scan729spec.run(): self.spec729(self.specrange, self.spec_729_period, reptime=100, …) */
static void experiment_run(volatile int32_t *P, volatile int32_t *span, int32_t npts, int32_t reps,
                           volatile int32_t *pmt) {
    spec729(P, span, npts, reps, pmt);
}
#endif
